private function normalize_google_fonts_url( $url ) {
    if ( false === strpos( $url, 'fonts.googleapis.com' ) ) {
        return '';
    }

    if ( false !== strpos( $url, '/css2' ) ) {
        return $url;
    }

    // For v1 URLs, keep using /css endpoint with same URL to avoid format conversion issues.
    return $url;
}

private function download_font_file( $url, $dest ) {
    $tmp = $dest . '.tmp.' . wp_rand();
    $response = wp_remote_get(
        $url,
        array(
            'timeout'    => 30,
            'user-agent' => self::CHROME_UA,
            'stream'     => true,
            'filename'   => $tmp,
        )
    );

    if ( is_wp_error( $response ) || 200 !== wp_remote_retrieve_response_code( $response ) ) {
        if ( file_exists( $tmp ) ) {
            wp_delete_file( $tmp );
        }
        return false;
    }

    $result = rename( $tmp, $dest );
    if ( ! $result && file_exists( $tmp ) ) {
        wp_delete_file( $tmp );
    }

    return file_exists( $dest );
}
